      loop(lod ? 2 : 6, i => H.b(m.chrome, .0262, .0022, .0045, 0, .0085, .292 + i * .009).b(m.chrome, .0242, .0022, .0045, 0, .029, .337 - i * .0001 + (i % 2) * .004));
